def _cooperative_outcome_tree(group, original_tree):
    """Six whole source views; invert every one of the seventeen substitutions."""
    if group not in VIEW_SPECS:
        raise ValueError('only the two declared outcome source modules are lifted')
    result = copy.deepcopy(original_tree)
    inverses = {}
    for index, original in enumerate(original_tree.body):
        if not isinstance(original, ast.FunctionDef) or original.name not in VIEW_SPECS[group]:
            continue
        source = EXPECTED_SOURCE[MODULE_PATHS[group]][original.name]
        if _dump(original) != _dump(ast.parse(source).body[0]):
            raise ValueError('complete reviewed outcome owner differs: ' + original.name)
        if any(isinstance(node, (ast.Yield, ast.YieldFrom)) for node in ast.walk(original)):
            raise ValueError('outcome source owner must retain its original synchronous body')
        spec = VIEW_SPECS[group][original.name]
        counts = {name: 0 for name in spec}
        replacements = []

        class Lift(ast.NodeTransformer):
            def visit_Call(self, node):
                node = self.generic_visit(node)
                if not isinstance(node.func, ast.Name) or node.func.id not in spec:
                    return node
                before = copy.deepcopy(node)
                name = node.func.id
                counts[name] += 1
                node.func.id = spec[name][1]
                after = ast.copy_location(ast.YieldFrom(value=node), node)
                replacements.append((before, copy.deepcopy(after)))
                return after

        derived = Lift().visit(copy.deepcopy(original))
        if counts != {name: value[0] for name, value in spec.items()}:
            raise ValueError('exact whole outcome propagation count differs: ' + original.name)
        pending = list(replacements)

        class Inverse(ast.NodeTransformer):
            def visit_YieldFrom(self, node):
                for position, (before, after) in enumerate(pending):
                    if _dump(node) == _dump(after):
                        pending.pop(position)
                        return ast.copy_location(copy.deepcopy(before), node)
                raise ValueError('unadmitted outcome yield-from')

        inverse = Inverse().visit(copy.deepcopy(derived))
        if pending or _dump(inverse) != _dump(original):
            raise ValueError('whole outcome function inverse differs: ' + original.name)
        result.body[index] = derived
        inverses[index] = inverse
    if len(inverses) != len(VIEW_SPECS[group]):
        raise ValueError('all complete outcome source owners are required')
    restored = copy.deepcopy(result)
    for index, inverse in inverses.items():
        restored.body[index] = inverse
    if _dump(restored) != _dump(original_tree):
        raise ValueError('whole outcome source-module inverse differs')
    return ast.fix_missing_locations(result)


def _outcome_message_bindings(module):
    """Retain the complete shared module and actual function/method code owners."""
    tree = ast.parse(inspect.getsource(module), filename=module.__file__)
    if _dump(tree) != EXPECTED_MESSAGE_AST:
        raise ValueError('complete reviewed shared outcome-message source required')
    plain = compile(tree, module.__file__, 'exec', dont_inherit=True)
    bindings = {}
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            owner = vars(module).get(node.name)
            if (type(owner) is not FunctionType or owner.__globals__ is not vars(module)
                    or owner.__module__ != module.__name__ or owner.__name__ != node.name
                    or owner.__closure__ is not None or owner.__code__.co_freevars
                    or _code_shape(owner.__code__) != _code_shape(_top_code(plain, node.name))):
                raise ValueError('actual shared outcome-message function required: ' + node.name)
            bindings[None, node.name] = owner, owner.__code__
        elif isinstance(node, ast.ClassDef):
            owner = vars(module).get(node.name)
            if type(owner) is not type or owner.__module__ != module.__name__ or owner.__name__ != node.name:
                raise ValueError('actual shared outcome-message class required')
            bindings[node.name, None] = owner, None
            class_code = _top_code(plain, node.name)
            for member in node.body:
                if not isinstance(member, ast.FunctionDef):
                    continue
                actual = vars(owner).get(member.name)
                codes = [value for value in class_code.co_consts if type(value) is CodeType
                    and value.co_name == member.name and value.co_qualname == node.name + '.' + member.name]
                if (member.decorator_list or len(codes) != 1 or type(actual) is not FunctionType
                        or actual.__globals__ is not vars(module) or actual.__module__ != module.__name__
                        or actual.__qualname__ != node.name + '.' + member.name
                        or actual.__closure__ is not None or actual.__code__.co_freevars
                        or _code_shape(actual.__code__) != _code_shape(codes[0])):
                    raise ValueError('actual shared outcome-message method required: ' + member.name)
                bindings[node.name, member.name] = actual, actual.__code__
    return bindings


class BattleOutcomeScenePrograms(BattlePreparationPrograms):
    """Entered4A8 retains3CE/4FA and the saved F362 WORD during real messages.

    Synchronous loss/ratio/resource/roster children keep their original owner
    and helper namespace. The private aliases below cannot turn their shared
    synchronous call helper into a generator accidentally.
    """

    def __init__(self, state):
        super().__init__(state)
        self.outcome_modules = {path: importlib.import_module(path) for path in EXPECTED_SOURCE}
        self.outcome_originals = {}
        self.outcome_codes = {}
        trees = {}
        for path, sources in EXPECTED_SOURCE.items():
            module = self.outcome_modules[path]
            tree = trees[path] = ast.parse(inspect.getsource(module), filename=module.__file__)
            plain = compile(tree, module.__file__, 'exec', dont_inherit=True)
            nodes = {node.name: node for node in tree.body if isinstance(node, ast.FunctionDef)}
            for name, text in sources.items():
                original = getattr(module, name)
                if (name not in nodes or _dump(nodes[name]) != _dump(ast.parse(text).body[0])
                        or type(original) is not FunctionType or original.__globals__ is not vars(module)
                        or original.__module__ != module.__name__ or original.__name__ != name
                        or original.__closure__ is not None or original.__code__.co_freevars
                        or _code_shape(original.__code__) != _code_shape(_top_code(plain, name))):
                    raise ValueError('actual complete unwrapped outcome source required: ' + path + ':' + name)
                self.outcome_originals[path, name] = original
                self.outcome_codes[path, name] = original.__code__
        self.outcome_views, self.outcome_namespaces = {}, {}
        for group, path in MODULE_PATHS.items():
            module = self.outcome_modules[path]
            derived = compile(_cooperative_outcome_tree(group, trees[path]), module.__file__, 'exec', dont_inherit=True)
            namespace = self.outcome_namespaces[group] = dict(vars(module))
            for name in VIEW_SPECS[group]:
                original = self.outcome_originals[path, name]
                view = FunctionType(_top_code(derived, name), namespace, name, original.__defaults__, None)
                view.__kwdefaults__ = original.__kwdefaults__
                view.__annotations__ = dict(original.__annotations__)
                if view.__closure__ is not None or not inspect.isgeneratorfunction(view):
                    raise ValueError('whole closure-free outcome generator required: ' + name)
                self.outcome_views[group, name] = view
        self._outcome_view_owners = dict(self.outcome_views)
        self._outcome_view_codes = {key: view.__code__ for key, view in self.outcome_views.items()}
        aliases = {'_outcome_view_' + name: view
            for (group, name), view in self.outcome_views.items() if group == 'battle'}
        aliases.update(_outcome_campaign_call=self.views['main', '_campaign_call_fields'],
            _outcome_message=self._outcome_message)
        self.outcome_bindings = {}
        for group, namespace in self.outcome_namespaces.items():
            for name, value in aliases.items():
                if name in namespace:
                    raise ValueError('outcome continuation must not shadow an original business name')
                namespace[name] = value
                self.outcome_bindings[group, name] = value
        from . import message_scene_steps
        self.outcome_message_module = message_scene_steps
        self.outcome_message_bindings = _outcome_message_bindings(message_scene_steps)
        if message_scene_steps.GameplayMessageScenePrograms is not GameplayMessageScenePrograms:
            raise ValueError('one actual shared outcome-message class binding required')
        self.outcome_message_scene = GameplayMessageScenePrograms(self)
        self._outcome_message_owner = self.outcome_message_scene

    def require_current(self, state):
        super().require_current(state)
        for (path, name), original in getattr(self, 'outcome_originals', {}).items():
            if getattr(self.outcome_modules[path], name) is not original or original.__code__ is not self.outcome_codes[path, name]:
                raise ValueError('actual outcome dependency changed during suspension: ' + name)
        if hasattr(self, '_outcome_view_owners'):
            if self.outcome_views.keys() != self._outcome_view_owners.keys():
                raise ValueError('whole outcome continuation graph changed')
            for key, view in self._outcome_view_owners.items():
                if self.outcome_views[key] is not view or view.__code__ is not self._outcome_view_codes[key]:
                    raise ValueError('actual whole outcome view changed: ' + key[1])
            for (group, name), value in getattr(self, 'outcome_bindings', {}).items():
                if self.outcome_namespaces[group].get(name) is not value:
                    raise ValueError('private outcome continuation binding changed: ' + name)
        if hasattr(self, 'outcome_message_bindings'):
            module = self.outcome_message_module
            if module.GameplayMessageScenePrograms is not GameplayMessageScenePrograms:
                raise ValueError('shared outcome-message class was rebound')
            for (class_name, name), (owner, code) in self.outcome_message_bindings.items():
                actual = vars(module).get(name) if class_name is None else vars(module).get(class_name)
                if class_name is not None and name is not None:
                    actual = vars(actual).get(name) if type(actual) is type else None
                if actual is not owner or (code is not None and actual.__code__ is not code):
                    raise ValueError('actual shared outcome-message owner changed')
        if hasattr(self, '_outcome_message_owner') and (self.outcome_message_scene is not self._outcome_message_owner
                or type(self.outcome_message_scene) is not GameplayMessageScenePrograms
                or self.outcome_message_scene.provider is not self):
            raise ValueError('same exact shared outcome-message instance required')

    def _outcome_message(self, memory, frame):
        self.require_current(memory.state)
        if type(memory) is not SceneRefreshMemory or frame.stack_cursor is None or frame.stack_cursor.state is not memory.state:
            raise MovementContinuationBoundary(0x30A74, frame, 'not one of the three original city-outcome message slots')
        return (yield from self._message_waits(self.outcome_message_scene.program(memory, frame)))

    def _campaign_child(self, state, frame, target, continuation):
        self.require_current(state)
        if (target, continuation) == (0x1BFEC, 0x4FA):
            return (yield from self.outcome_views['battle', 'settle_city_battle_outcome_fields'](
                BattlePresentationMemory(state), frame))
        if (target, continuation) == (0xAF48, 0x500):
            return (yield from self._refresh(SceneRefreshMemory(state), frame))
        return (yield from super()._campaign_child(state, frame, target, continuation))

    def _display_child(self, state, frame, target, continuation):
        self.require_current(state)
        if target in MAIN_ENTRIES:
            if continuation != 0x3CE:
                raise MovementContinuationBoundary(target, frame, 'outcome Main4A8 requires original3CE LONG')
            return (yield from self.outcome_views['main', MAIN_ENTRIES[target]](state, frame))
        return (yield from super()._display_child(state, frame, target, continuation))

    def main_scene_call(self, state, frame, target, continuation):
        if target not in MAIN_ENTRIES:
            return (yield from super().main_scene_call(state, frame, target, continuation))
        self.require_current(state)
        if self._started or continuation != 0x3CE:
            raise ValueError('one complete original Main4A8/3CE invocation required')
        self._started = True
        return (yield from self.views['display', 'display_call_fields'](state, frame, target, continuation))
